 "content": "from collections import deque


def transform(grid):
    """Periodically extend each corner motif across its zero-filled panel."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 8 and (nr,nc) not in seen:
                        seen.add((nr,nc)); q.append((nr,nc))
            r0, r1 = min(x for x,y in cells), max(x for x,y in cells)
            c0, c1 = min(y for x,y in cells), max(y for x,y in cells)
            marks = [(x,y) for x,y in cells if grid[x][y] != 0]
            if not marks:
                continue
            mr0, mr1 = min(x for x,y in marks), max(x for x,y in marks)
            mc0, mc1 = min(y for x,y in marks), max(y for x,y in marks)
            mh, mw = mr1-mr0+1, mc1-mc0+1
            motif = [row[mc0:mc1+1] for row in grid[mr0:mr1+1]]
            # The seed is placed in one corner; use that corner as the tiling anchor.
            bottom = (mr0-r0) > (r1-mr1)
            right = (mc0-c0) > (c1-mc1)
            for rr in range(r0,r1+1):
                ir = (rr-mr0) % mh if not bottom else (mr1-rr) % mh
                if bottom:
                    ir = mh-1-ir
                for cc in range(c0,c1+1):
                    ic = (cc-mc0) % mw if not right else (mc1-cc) % mw
                    if right:
                        ic = mw-1-ic
                    out[rr][cc] = motif[ir][ic]
    return out
