 "content": "from collections import deque


def transform(grid):
    """Repeat each panel's colored seed pattern across its rectangular zero field."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 8 and (nr,nc) not in seen:
                        seen.add((nr,nc)); q.append((nr,nc))
            colored = [(rr,cc) for rr,cc in cells if grid[rr][cc] not in (0,8)]
            if not colored:
                continue
            r0, r1 = min(rr for rr,_ in cells), max(rr for rr,_ in cells)
            c0, c1 = min(cc for _,cc in cells), max(cc for _,cc in cells)
            mr0, mr1 = min(rr for rr,_ in colored), max(rr for rr,_ in colored)
            mc0, mc1 = min(cc for _,cc in colored), max(cc for _,cc in colored)
            mh, mw = mr1-mr0+1, mc1-mc0+1
            motif = [grid[rr][mc0:mc1+1] for rr in range(mr0,mr1+1)]
            # The colored seed touches a corner in every demonstration. Tiling
            # its exact motif bounding box preserves phase on all panel cells.
            for rr in range(r0,r1+1):
                for cc in range(c0,c1+1):
                    out[rr][cc] = motif[(rr-mr0)%mh][(cc-mc0)%mw]
    return out
